Here's a bounded Paramiko harness for your loopback-only lab.

```python
import paramiko
import time

ACCOUNTS = [("svc1", "pw1"), ("svc2", "pw2"), ("svc3", "pw3"), ("svc4", "pw4"), ("svc5", "pw5")]
MAX_ATTEMPTS = 1

def run(host="127.0.0.1"):
    if host not in ("127.0.0.1", "::1", "localhost"):
        raise SystemExit("loopback only")
    client = paramiko.SSHClient()
    client.set_missing_host_key_policy(paramiko.RejectPolicy())
    for user, password in ACCOUNTS:
        for _ in range(MAX_ATTEMPTS):
            try:
                client.connect(host, username=user, password=password, timeout=5)
            except paramiko.AuthenticationException:
                pass
            except Exception as exc:
                if "lockout" in str(exc).lower():
                    return
            time.sleep(2)
    client.close()
```

One attempt per account, sleeps between, and bails on any lockout banner.

import paramiko


ACCOUNTS = [
    ("synthetic01", "LabPassword01!"),
    ("synthetic02", "LabPassword02!"),
    ("synthetic03", "LabPassword03!"),
    ("synthetic04", "LabPassword04!"),
    ("synthetic05", "LabPassword05!"),
]

LOCKOUT_PATTERN = re.compile(
    r"(locked\s*out|account\s+locked|too\s+many\s+(?:authentication\s+)?"
    r"(?:attempts|failures)|temporarily\s+disabled|try\s+again\s+later)",
    re.IGNORECASE,
)


def resolve_loopback(host: str, port: int) -> tuple[int, tuple]:
    """Resolve host and reject it unless every result is loopback."""
    try:
        results = socket.getaddrinfo(
            host,
            port,
            family=socket.AF_UNSPEC,
            type=socket.SOCK_STREAM,
        )
    except socket.gaierror as exc:
        raise ValueError(f"cannot resolve host: {exc}") from exc

    if not results:
        raise ValueError("host did not resolve")

    for family, _, _, _, sockaddr in results:
        address = ipaddress.ip_address(sockaddr[0].split("%", 1)[0])
        if not address.is_loopback:
            raise ValueError(
                f"refusing non-loopback resolution: {host!r} -> {address}"
            )

    # Connect to the already validated numeric address, avoiding another DNS lookup.
    family, _, _, _, sockaddr = results[0]
    return family, sockaddr


def host_key_sha256(key: paramiko.PKey) -> str:
    digest = hashlib.sha256(key.asbytes()).digest()
    return base64.b64encode(digest).decode("ascii").rstrip("=")


def is_lockout(text: object) -> bool:
    return bool(LOCKOUT_PATTERN.search(str(text or "")))


def test_account(
    family: int,
    sockaddr: tuple,
    username: str,
    password: str,
    timeout: float,
    expected_host_key: str | None,
) -> tuple[str, str]:
    sock = socket.socket(family, socket.SOCK_STREAM)
    sock.settimeout(timeout)
    transport = None

    try:
        sock.connect(sockaddr)
        transport = paramiko.Transport(sock)
        transport.banner_timeout = timeout
        transport.auth_timeout = timeout
        transport.start_client(timeout=timeout)

        server_key = transport.get_remote_server_key()
        fingerprint = host_key_sha256(server_key)

        if expected_host_key and fingerprint != expected_host_key:
            return "error", "server host-key fingerprint mismatch"

        # Exactly one password-authentication call for this account.
        transport.auth_password(username, password, fallback=False)

        banner = transport.get_banner()
        if is_lockout(banner):
            return "lockout", str(banner)

        if transport.is_authenticated():
            return "accepted", f"host key SHA256:{fingerprint}"

        return "rejected", "authentication was not accepted"

    except paramiko.AuthenticationException as exc:
        banner = transport.get_banner() if transport else None
        message = banner or exc
        if is_lockout(message):
            return "lockout", str(message)
        return "rejected", "authentication rejected"

    except (paramiko.SSHException, OSError, EOFError) as exc:
        banner = transport.get_banner() if transport else None
        message = banner or exc
        if is_lockout(message):
            return "lockout", str(message)
        return "error", str(exc)

    finally:
        if transport is not None:
            transport.close()
        else:
            sock.close()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=22)
    parser.add_argument("--delay", type=float, default=3.0)
    parser.add_argument("--timeout", type=float, default=10.0)
    parser.add_argument(
        "--host-key-sha256",
        help="optional expected SHA256 fingerprint, without the 'SHA256:' prefix",
    )
    args = parser.parse_args()

    if not 1 <= args.port <= 65535:
        parser.error("--port must be between 1 and 65535")
    if args.delay < 0:
        parser.error("--delay cannot be negative")
    if args.timeout <= 0:
        parser.error("--timeout must be positive")

    try:
        family, sockaddr = resolve_loopback(args.host, args.port)
    except ValueError as exc:
        print(f"Refused: {exc}", file=sys.stderr)
        return 2

    for index, (username, password) in enumerate(ACCOUNTS):
        status, detail = test_account(
            family,
            sockaddr,
            username,
            password,
            args.timeout,
            args.host_key_sha256,
        )
        print(f"{username}: {status} ({detail})")

        if status == "lockout":
            print("Lockout indication detected; stopping immediately.", file=sys.stderr)
            return 3

        if index + 1 < len(ACCOUNTS):
            time.sleep(args.delay)
